          <button 
            className="wf-modal-close" 
            onClick={() => setEditingVideo(null)}
            style={{ 
              position: 'absolute', 
              top: '-15px', 
              right: '-15px', 
              background: '#ef4444', 
              color: 'white', 
              border: '2px solid white', 
              borderRadius: '50%', 
              width: '30px', 
              height: '30px', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center', 
              cursor: 'pointer',
